diff --git a/tests/factura.test.mjs b/tests/factura.test.mjs
index fabcb45..2d9eb05 100644
--- a/tests/factura.test.mjs
+++ b/tests/factura.test.mjs
@@ -30,6 +30,54 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+const LINEAS_RF006 = [
+  { cantidad: 2, precioUnitarioCentavos: 5000 },
+  { cantidad: 1, precioUnitarioCentavos: 1050 },
+];
+
+test("P-01 RF-006: sin descuentoGlobal el resultado no cambia", () => {
+  const esperado = { totalCentavos: 11050, ivaCentavos: 1437, netoCentavos: 9613 };
+  assert.deepEqual(calcularFactura(LINEAS_RF006), esperado);
+  assert.deepEqual(calcularFactura(LINEAS_RF006, {}), esperado);
+});
+
+test("P-02 RF-006: 10 % global, IVA y neto sobre el total descontado", () => {
+  assert.deepEqual(calcularFactura(LINEAS_RF006, { descuentoGlobal: 10 }), {
+    totalCentavos: 9945,
+    ivaCentavos: 1293,
+    netoCentavos: 8652,
+  });
+});
+
+test("P-03 RF-006: 0 % no cambia y 100 % deja todo en 0", () => {
+  assert.equal(calcularFactura(LINEAS_RF006, { descuentoGlobal: 0 }).totalCentavos, 11050);
+  assert.deepEqual(calcularFactura(LINEAS_RF006, { descuentoGlobal: 100 }), {
+    totalCentavos: 0,
+    ivaCentavos: 0,
+    netoCentavos: 0,
+  });
+});
+
+test("P-04 RF-006: descuento fuera de 0–100 o no entero se rechaza", () => {
+  for (const d of [-1, 101, 12.5, "10", NaN]) {
+    assert.throws(() => calcularFactura(LINEAS_RF006, { descuentoGlobal: d }), RangeError);
+  }
+});
+
+test("P-05 RF-006: el redondeo al centavo es entero", () => {
+  const r = calcularFactura([{ cantidad: 3, precioUnitarioCentavos: 333 }], { descuentoGlobal: 15 });
+  assert.equal(r.totalCentavos, 849);
+  for (const v of Object.values(r)) assert.ok(Number.isInteger(v));
+});
+
+test("P-06 RF-006: emitirFactura con descuento global queda congelada", () => {
+  const f = emitirFactura({ numero: 8, nit: "1023456", razonSocial: "Cliente SA", items: LINEAS_RF006, descuentoGlobal: 10 });
+  assert.ok(Object.isFrozen(f));
+  assert.equal(f.estado, "emitida");
+  assert.equal(f.totalCentavos, 9945);
+  assert.equal(f.netoCentavos, 8652);
+});
+
